-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
local item_lib = require("items")

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 29626 }) then
    e.self:Emote("turns towards you as you toss the device at him. Startled, the golem catches the device as it suddenly begins to whine. His image begins to fade and is replaced with that of a Kromzek warrior!")
    local attacker = eq.spawn2(114437, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading())
    attacker:AddToHateList(e.other, 1)
    eq.depop_with_timer()
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
